import {C,$,save,on,modal,esc,toast,wait,confirm} from './studio-ui.js';
import {hub,putHub,clone,uid,changed,invalidateChain,logJob,taskSnapshot,setGeneration} from './workflow-store.js';
import {generateSpeech,dialogueText} from './studio-director.js';
export function prepareElements(){const s=C.s;s.projectElements??=[];for(const sh of s.shots)for(const a of sh.assets.filter(a=>['角色','场景','道具'].includes(a.kind))){let entity=s.projectElements.find(x=>x.id===a.entityId)||s.projectElements.find(x=>x.kind===a.kind&&x.name===a.name);if(!entity){entity={id:uid('entity'),kind:a.kind,name:a.name,description:a.description,voice:'默认音色',threeViews:false,reference:null,image:a.image,version:a.version||1};s.projectElements.push(entity)}a.entityId=entity.id;}}
function sync(entity,visual=true){const s=C.s;s.shots.forEach((sh,i)=>{let affected=false;sh.assets.filter(a=>a.entityId===entity.id).forEach(a=>{a.name=entity.name;a.description=entity.description;if(visual&&entity.image)a.image=entity.image;a.version++;a.confirmed=false;affected=true});if(affected){sh.dialogue=dialogueText(sh);if(visual)invalidateChain(s,i);else changed(s,i);if(sh.audio)sh.audio.stale=true;for(const d of sh.dialogues||[])if(d.speaker===entity.name){d.voice=entity.voice;if(d.audio)d.audio.stale=true;}}});}
function readImage(file,done){if(!file)return;if(file.size>2*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('请选择不超过 2MB 的 PNG、JPG 或 WebP 图片');const r=new FileReader();r.onload=()=>done(r.result);r.onerror=()=>toast('图片读取失败，请重新选择');r.readAsDataURL(file)}
export function elementArt(kind){const paths={角色:'<circle cx="130" cy="62" r="30"/><path d="M75 155q5-62 55-62t55 62"/>',场景:'<path d="M45 100L130 30l85 70v70H45Z"/><rect x="107" y="110" width="46" height="60" fill="#cad9dc"/>',道具:'<path d="M70 65l60-30 60 30v85l-60 30-60-30Z"/>',站位:'<circle cx="70" cy="90" r="22"/><circle cx="190" cy="90" r="22"/><path d="M105 90h48l-12-12m12 12-12 12" fill="none" stroke="#355b75" stroke-width="4"/>'};return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="260" height="200"><rect width="260" height="200" fill="#cad9dc"/><g fill="#355b75">${paths[kind]||paths.场景}</g><text x="130" y="192" font-size="12" text-anchor="middle" fill="#243e50">${kind} · 生成示例</text></svg>`)}
export function elementManager(kind){prepareElements();const s=C.s,items=s.projectElements.filter(e=>e.kind===kind);const d=modal(`${kind}管理`, `<p class="helper">管理整部短片的${kind}。已有镜头按稳定 ID 引用；修改后相关素材需重新确认。</p><div class="element-toolbar"><button class="button" id="add-element">新增${kind}</button><button class="button" id="batch-element">批量生成${kind}图片</button><span>${items.length} 个${kind}</span></div><div class="element-scroll"><table class="element-table"><thead><tr><th>名称</th><th>${kind}描述${kind==='角色'?' / 音色':''}</th><th>参考图</th><th>生成图片</th><th>操作</th></tr></thead><tbody>${items.map(e=>`<tr data-entity="${e.id}"><td><input aria-label="${esc(e.name)}名称" data-entity-name="${e.id}" value="${esc(e.name)}"></td><td><textarea aria-label="${esc(e.name)}描述" data-entity-desc="${e.id}">${esc(e.description)}</textarea>${kind==='角色'?`<label class="field">音色<select data-entity-voice="${e.id}">${['默认音色','温暖女声','沉稳男声','清亮少年声',...s.libraryAssets?.filter(a=>a.kind==='声音').map(a=>a.name)||[]].map(v=>`<option ${v===e.voice?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="check"><input type="checkbox" data-entity-views="${e.id}" ${e.threeViews?'checked':''}>三视图</label>`:''}</td><td>${e.reference?`<img src="${esc(e.reference)}" alt="${esc(e.name)}参考图">`:'<div class="element-empty">未上传参考图</div>'}<label class="text-button file-label">上传<input type="file" data-entity-ref="${e.id}" accept="image/png,image/jpeg,image/webp"></label></td><td>${e.image?`<img src="${esc(e.image)}" alt="${esc(e.name)}生成图">`:'<div class="element-empty">尚未生成</div>'}<label class="text-button file-label">上传图片<input type="file" data-entity-image="${e.id}" accept="image/png,image/jpeg,image/webp"></label></td><td><button class="button" data-generate-entity="${e.id}">生成图片</button><button class="text-button" data-library-entity="${e.id}">存入资产库</button><button class="text-button" data-bind-entity="${e.id}">绑定镜头</button><button class="text-button danger" data-remove-entity="${e.id}">删除</button></td></tr>`).join('')}</tbody></table>${items.length?'':'<div class="empty-state">暂无元素，点击新增或先生成分镜。</div>'}</div>`, '<button class="button primary" id="save-elements">保存修改</button>');d.classList.add('element-manager');d.addEventListener('close',()=>d.classList.remove('element-manager'),{once:true});
function hold(){let valid=true;for(const e of items){const n=document.querySelector(`[data-entity-name="${e.id}"]`).value.trim();if(!n){toast('元素名称不能为空');valid=false;break}}if(!valid)return false;for(const e of items){const n=document.querySelector(`[data-entity-name="${e.id}"]`).value.trim(),description=document.querySelector(`[data-entity-desc="${e.id}"]`).value,voice=document.querySelector(`[data-entity-voice="${e.id}"]`)?.value||e.voice,threeViews=document.querySelector(`[data-entity-views="${e.id}"]`)?.checked||false;if(n!==e.name||description!==e.description||voice!==e.voice||threeViews!==e.threeViews){const old=e.name;Object.assign(e,{name:n,description,voice,threeViews,version:e.version+1});for(const sh of s.shots)for(const line of sh.dialogues||[])if(line.speaker===old)line.speaker=n;sync(e,false);}}return save()}
function redraw(){d.close();C.render();elementManager(kind)}
on('save-elements',()=>{if(hold()){d.close();C.render();toast('全片元素已保存；受影响镜头已标记待更新')}});on('add-element',()=>{if(!hold())return;s.projectElements.push({id:uid('entity'),kind,name:`新${kind} ${items.length+1}`,description:'',voice:'默认音色',version:1});save();redraw()});function generate(e){e.image=elementArt(kind);e.version++;sync(e);logJob(s,{角色:'characterImage',场景:'sceneImage',道具:'propImage'}[kind],{entityId:e.id,description:e.description,threeViews:e.threeViews,image:e.image});}on('batch-element',()=>{if(!hold())return;items.forEach(generate);save();redraw();toast('已生成图片示例，请检查后在分镜确认')});document.querySelectorAll('[data-generate-entity]').forEach(b=>b.onclick=()=>{if(!hold())return;generate(items.find(e=>e.id===b.dataset.generateEntity));save();redraw()});for(const [attr,field]of [['ref','reference'],['image','image']])document.querySelectorAll(`[data-entity-${attr}]`).forEach(input=>input.onchange=()=>{if(!hold())return;const e=items.find(e=>e.id===input.dataset['entity'+attr[0].toUpperCase()+attr.slice(1)]);readImage(input.files[0],data=>{e[field]=data;e.version++;if(field==='image')sync(e);save();redraw()})});document.querySelectorAll('[data-library-entity]').forEach(b=>b.onclick=()=>{if(!hold())return;const e=items.find(e=>e.id===b.dataset.libraryEntity),h=hub();h.assets.push({...clone(e),id:uid('library')});putHub(h);toast('已加入资产库')});document.querySelectorAll('[data-remove-entity]').forEach(b=>b.onclick=()=>{if(!hold())return;const e=items.find(e=>e.id===b.dataset.removeEntity);if(s.shots.some(sh=>sh.assets.some(a=>a.entityId===e.id)))return toast('该元素仍被镜头引用，请先替换引用后再删除');s.projectElements=s.projectElements.filter(x=>x.id!==e.id);save();redraw()});document.querySelectorAll('[data-bind-entity]').forEach(b=>b.onclick=()=>{if(!hold())return;const e=items.find(e=>e.id===b.dataset.bindEntity);d.close();const bind=modal('绑定镜头',`<label class="field">选择镜头<select id="bind-shot">${s.shots.map((sh,i)=>`<option value="${sh.id}">镜头 ${i+1}</option>`).join('')}</select></label><label class="field">绑定方式<select id="bind-mode"><option value="add">添加为参考元素</option><option value="replace">替换首个同类元素</option></select></label><p>添加保留已有角色；替换保留被替换图片的引用 ID。</p>`, '<button class="button primary" id="apply-bind">确认绑定</button>');on('apply-bind',()=>{const sh=s.shots.find(x=>x.id===$('bind-shot').value);if(!sh)return toast('请先生成分镜');if(sh.assets.some(a=>a.entityId===e.id))return toast('该镜头已引用此元素');let a=$('bind-mode').value==='replace'?sh.assets.find(a=>a.kind===kind):null;if(!a){a={id:uid('ref'),kind,version:0};sh.assets.push(a);sh.prompt+=` @[${a.id}]`;}Object.assign(a,{entityId:e.id,name:e.name,description:e.description,image:e.image,version:a.version+1,confirmed:false});changed(s,s.shots.indexOf(sh));save();bind.close();C.render()})});}
export function generationSettings(system=false,afterSave){const s=C.s,h=hub(),g=system?(h.config.generationDefaults||{aspect:'',resolution:'1080P',model:'演示视频模型'}):(s.generation?.aspect?s.generation:{...(h.config.generationDefaults||{resolution:'1080P',model:s.models.video?.name||'演示视频模型'}),aspect:h.config.generationDefaults?.aspect||''});const d=modal(system?'视频输出默认设置':'分镜生成设置',`<p class="helper">${system?'保存为新项目立项的建议默认值；不覆盖已有项目。':'继承项目立项规格；修改后同步视频生成与导出，已有素材需重新确认。'}</p><div class="field-pair"><label class="field">视频画面比例<select id="generation-aspect"><option value="">请选择画面比例</option>${['9:16','16:9','1:1'].map(v=>`<option ${v===(g.aspect||(!system?h.config.generationDefaults?.aspect:''))?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">视频分辨率<select id="generation-resolution">${['720P','1080P','4K'].map(v=>`<option ${v===g.resolution?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="field">视频模型<input id="generation-model" value="${esc(g.model||s.models.video?.name||'演示视频模型')}"></label><p class="helper" id="generation-size">尺寸按比例与分辨率计算。</p><p class="helper">真实服务路由、地址和凭据引用在系统设置的大模型配置中维护。</p>`, '<button class="button primary" id="save-generation">保存'+(afterSave?'并AI生成分镜':'设置')+'</button>');function size(){const a=$('generation-aspect').value,r=$('generation-resolution').value,short={'720P':720,'1080P':1080,'4K':2160}[r];$('generation-size').textContent=a?`输出尺寸：${a==='1:1'?short+' × '+short:a==='16:9'?Math.round(short*16/9)+' × '+short:short+' × '+Math.round(short*16/9)} px`:'请选择画面比例';}size();$('generation-aspect').onchange=size;$('generation-resolution').onchange=size;on('save-generation',()=>{const v={aspect:$('generation-aspect').value,resolution:$('generation-resolution').value,model:$('generation-model').value.trim()};if(!v.aspect||!v.model)return toast('请选择画幅并填写模型');if(system){h.config.generationDefaults=v;putHub(h)}else{setGeneration(s,v);save()}d.close();C.render();if(afterSave)afterSave();});}
export function boardTools(){return `<div class="production-tools" id="production-tools"><button class="button" data-elements="角色">角色管理</button><button class="button" data-elements="场景">场景管理</button><button class="button" data-elements="道具">道具管理</button><button class="button" id="batch-speech">批量配音</button><button class="button" id="batch-blocking">批量站位图</button><button class="button" id="generation-settings">生成设置</button></div>`}
export function bindBoardTools(){document.querySelectorAll('[data-elements]').forEach(b=>b.onclick=()=>elementManager(b.dataset.elements));on('generation-settings',()=>generationSettings());on('batch-speech',async()=>{if(!C.s.shots.length)return toast('请先生成分镜');$('batch-speech').disabled=true;let done=0;for(const sh of C.s.shots)if(await generateSpeech(sh))done++;C.render();toast(`配音示例完成 ${done} 个镜头，${C.s.shots.length-done} 个因台词未补齐而跳过`)});on('batch-blocking',()=>{if(!C.s.shots.length)return toast('请先生成分镜');for(const sh of C.s.shots){const a=sh.assets.find(a=>a.kind==='站位');if(!a)continue;a.image=elementArt('站位');a.version++;a.confirmed=false;invalidateChain(C.s,C.s.shots.indexOf(sh));logJob(C.s,'blockingImage',{shotId:sh.id,assetId:a.id,image:a.image})}save();C.render();toast('站位图已生成，请检查朝向与空间关系')});}
